import { test, expect } from '@playwright/test';

test.describe('Tab Navigation with URL Hash Update', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/page-with-tabs');
  });

  test('should update URL hash when clicking a tab', async ({ page }) => {
    // Verify initial URL does not have a hash
    await expect(page).toHaveURL('/page-with-tabs');

    // Click the first tab using getByRole
    const tab1 = page.getByRole('tab', { name: 'Tab 1' });
    await tab1.click();

    // Verify URL hash is updated to #tab-1
    await expect(page).toHaveURL(/#tab-1/);

    // Verify tab content is visible
    const tabContent = page.getByText('Content for Tab 1');
    await expect(tabContent).toBeVisible();

    // Click the second tab using getByRole
    const tab2 = page.getByRole('tab', { name: 'Tab 2' });
    await tab2.click();

    // Verify URL hash is updated to #tab-2
    await expect(page).toHaveURL(/#tab-2/);

    // Verify tab content is visible
    const tabContent2 = page.getByText('Content for Tab 2');
    await expect(tabContent2).toBeVisible();

    // Click the third tab using getByRole
    const tab3 = page.getByRole('tab', { name: 'Tab 3' });
    await tab3.click();

    // Verify URL hash is updated to #tab-3
    await expect(page).toHaveURL(/#tab-3/);

    // Verify tab content is visible
    const tabContent3 = page.getByText('Content for Tab 3');
    await expect(tabContent3).toBeVisible();
  });

  test('should navigate to a specific tab using URL hash and update content', async ({ page }) => {
    // Navigate directly to the second tab using URL hash
    await page.goto('/page-with-tabs#tab-2');

    // Verify URL hash is set to #tab-2
    await expect(page).toHaveURL(/#tab-2/);

    // Verify tab content is visible
    const tabContent = page.getByText('Content for Tab 2');
    await expect(tabContent).toBeVisible();

    // Verify tab button is active
    const tabButton = page.getByRole('tab', { name: 'Tab 2' });
    await expect(tabButton).toHaveAttribute('aria-selected', 'true');

    // Click the first tab using getByRole
    const tab1 = page.getByRole('tab', { name: 'Tab 1' });
    await tab1.click();

    // Verify URL hash is updated to #tab-1
    await expect(page).toHaveURL(/#tab-1/);

    // Verify tab content is visible
    const tabContent1 = page.getByText('Content for Tab 1');
    await expect(tabContent1).toBeVisible();

    // Verify tab button is active
    await expect(tab1).toHaveAttribute('aria-selected', 'true');

    // Click the third tab using getByRole
    const tab3 = page.getByRole('tab', { name: 'Tab 3' });
    await tab3.click();

    // Verify URL hash is updated to #tab-3
    await expect(page).toHaveURL(/#tab-3/);

    // Verify tab content is visible
    const tabContent3 = page.getByText('Content for Tab 3');
    await expect(tabContent3).toBeVisible();
  });
});
